import { useEffect } from 'react';
import { useThree } from '@react-three/fiber';
import * as THREE from 'three';
import { getCurrentDayPhase } from '../../game/worldClock.ts';
import type { WorldCoordinate } from '../../utils/worldCoordinates.ts';

// --- Collaborative vantage recorder ------------------------------------------
//
// Lets the USER fly/walk to a good camera position+rotation during NORMAL play
// and pin it WITH A REASON, so Claude can file it into vantages.json and the
// harness (AgentCamera + tools/capture.mjs) replays it EXACTLY on the right
// world/seed. Keys (debug-only; ` chosen so gameplay keys like C stay free):
//   `  -> pin: prompts for a reason / thing-of-interest, records the exact world-
//         space camera pose + the current WORLD COORDINATE (= seed) + dayphase.
//   V  -> copy ALL pinned vantages to the clipboard as JSON (paste to Claude).
// Pins also accumulate on window.__poses + localStorage. A toast confirms each
// (driven by the 'vantage:pinned' / 'vantage:copied' window events; see App).

const round = (n: number, d = 3) => Number(n.toFixed(d));
const slug = (s: string) =>
  s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'vantage';

interface PoseRecorderProps {
  coordinate: WorldCoordinate;
}

export default function PoseRecorder({ coordinate }: PoseRecorderProps) {
  const camera = useThree(state => state.camera);

  useEffect(() => {
    // eslint-disable-next-line no-console
    console.log('[poses] ` = pin a vantage (with reason)   V = copy all pins to clipboard');
    const w = window as unknown as { __poses?: unknown[] };

    const onKey = (event: KeyboardEvent) => {
      const el = document.activeElement;
      if (el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA')) return;

      if (event.code === 'Backquote') {
        // (Pointer lock is auto-released while the prompt is open; click to re-lock.)
===APPSTATE
 * Debug deep-links jump straight into the world and must SKIP the landing menu,
 * matching the existing ?fly/?descent/?world/?agent/?overview entry points in
 * App.tsx. Computed once from the URL at module load.
 */
// ?story values that stay on the MENU phase (the prologue terminal runs over it).
// Mirrors the prologue beats in story/storyState.ts — kept literal here so this
// low-level store doesn't import game systems at module load.
const MENU_STORY_PARAMS = ['1', 'crawl', 'manifest', 'voyage', 'deflect', 'crash'];

function computeDeepLink(): boolean {
  if (typeof window === 'undefined') return false;
  const p = new URLSearchParams(window.location.search);
  const story = p.get('story');
  return (
    p.has('world') ||
    p.get('fly') === '1' ||
    p.has('descent') ||
    p.get('agent') === '1' ||
    p.get('overview') === '1' ||
    // On-planet story jumps skip the menu; prologue jumps keep it (the terminal
    // overlay runs over the menu phase — see story/storyState.ts).
    (story !== null && !MENU_STORY_PARAMS.includes(story))
  );
}

const DEEP_LINK = computeDeepLink();

let snapshot: AppStateSnapshot = {
  phase: DEEP_LINK ? 'playing' : 'menu',
  sceneReady: false
};

function publishDebugSnapshot(): void {
  if (typeof window === 'undefined') return;
  (window as Window & { __paravoxiaAppState?: AppStateSnapshot }).__paravoxiaAppState = snapshot;
}
publishDebugSnapshot();

// Not part of the snapshot: these mutate every frame / often and must NOT
// trigger re-renders. We only emit when `sceneReady` actually flips.
let terrainPopulated = false;

